export function bech32Decode(bech) {
  if (typeof bech !== "string" || bech.length < 8 || bech.length > 90) {
    return null;
  }

  let hasLowerCase = false;
  let hasUpperCase = false;

  for (const character of bech) {
    const codePoint = character.codePointAt(0);

    if (codePoint < 33 || codePoint > 126) {
      return null;
    }

    if (character >= "a" && character <= "z") {
      hasLowerCase = true;
    } else if (character >= "A" && character <= "Z") {
      hasUpperCase = true;
    }
  }

  if (hasLowerCase && hasUpperCase) {
    return null;
  }

  const normalized = bech.toLowerCase();
  const separatorIndex = normalized.lastIndexOf("1");

  if (separatorIndex < 1 || separatorIndex + 7 > normalized.length) {
    return null;
  }

  const hrp = normalized.slice(0, separatorIndex);
  const data = [];

  for (const character of normalized.slice(separatorIndex + 1)) {
    const position = CHARSET.indexOf(character);

    if (position === -1) {
      return null;
    }

    data.push(position);
  }

  if (!bech32VerifyChecksum(hrp, data)) {
    return null;
  }

  return {
    hrp,
    data: data.slice(0, -6),
  };
}

