  if (stream === "stderr") {
    process.stderr.write(text);
    return;
  }

  process.stdout.write(text);
}

export function main(argv = process.argv) {
  const programName = getProgramName(argv);
  const parsedCommandLine = parseCommandLine(argv.slice(2), programName);

  if (parsedCommandLine.kind === "help" || parsedCommandLine.kind === "error") {
