import { bech32Decode, bech32Encode } from "./core.mjs";
import { convertBits } from "./convert_bits.mjs";
import { PythonIndexError } from "../runtime/errors.mjs";

function normalizeWitnessVersion(rawWitnessVersion) {
  if (rawWitnessVersion > 31n || rawWitnessVersion < -32n) {
    throw new PythonIndexError();
  }

  if (rawWitnessVersion < 0n || rawWitnessVersion > 16n) {
    return null;
  }

  return Number(rawWitnessVersion);
}

function normalizeWitnessProgram(rawWitnessProgram) {
  const witnessProgram = [];

  for (const rawByte of rawWitnessProgram) {
    if (rawByte < 0n || rawByte > 255n) {
      return null;
    }

    witnessProgram.push(Number(rawByte));
  }

  return witnessProgram;
}

export function decodeSegwitAddress(expectedHrp, address) {
  const decodedBech32 = bech32Decode(address);

  if (decodedBech32 === null || decodedBech32.hrp !== expectedHrp) {
    return null;
  }

  const [witnessVersion, ...programData] = decodedBech32.data;
  const witnessProgram = convertBits(programData, 5, 8, false);

  if (witnessProgram === null) {
    return null;
  }

  if (
    witnessProgram.length < 2 ||
    witnessProgram.length > 40 ||
    witnessVersion > 16 ||
    (witnessVersion === 0 && witnessProgram.length !== 20 && witnessProgram.length !== 32)
  ) {
    return null;
  }

  return {
    witnessVersion,
    witnessProgram,
  };
}

export function encodeSegwitAddress(hrp, rawWitnessVersion, rawWitnessProgram) {
  const witnessVersion = normalizeWitnessVersion(rawWitnessVersion);

  if (witnessVersion === null) {
    return null;
  }

  const witnessProgram = normalizeWitnessProgram(rawWitnessProgram);

  if (witnessProgram === null) {
    return null;
  }

  const convertedProgram = convertBits(witnessProgram, 8, 5, true);

  if (convertedProgram === null) {
    return null;
  }

  const encodedAddress = bech32Encode(hrp, [witnessVersion, ...convertedProgram]);
  return decodeSegwitAddress(hrp, encodedAddress) === null ? null : encodedAddress;
}

