import { GENERATORS } from "./constants.mjs";

export function bech32Polymod(values) {
  let checksum = 1;

  for (const value of values) {
    const top = checksum >>> 25;
    checksum = ((checksum & 0x1ffffff) << 5) ^ value;

    for (let index = 0; index < GENERATORS.length; index += 1) {
      if (((top >>> index) & 1) !== 0) {
        checksum ^= GENERATORS[index];
      }
    }
  }

  return checksum >>> 0;
}

export function bech32HrpExpand(hrp) {
  const expanded = [];

  for (const character of hrp) {
    const codePoint = character.codePointAt(0);
    expanded.push(codePoint >> 5);
  }

  expanded.push(0);

  for (const character of hrp) {
    const codePoint = character.codePointAt(0);
    expanded.push(codePoint & 31);
  }

  return expanded;
}

export function bech32CreateChecksum(hrp, data) {
  const polymod = bech32Polymod([...bech32HrpExpand(hrp), ...data, 0, 0, 0, 0, 0, 0]) ^ 1;
  const checksum = [];

  for (let index = 0; index < 6; index += 1) {
    checksum.push((polymod >> (5 * (5 - index))) & 31);
  }

  return checksum;
}

export function bech32VerifyChecksum(hrp, data) {
  return bech32Polymod([...bech32HrpExpand(hrp), ...data]) === 1;
}

