import { canConsumeOptionArgument, parsePythonDecimalBigInt } from "./python_int.mjs";
import { pythonStringRepr } from "../runtime/errors.mjs";

const OPTIONS = [
  { key: "a", flag: "--a", metavar: "A", type: "string" },
  { key: "b", flag: "--b", metavar: "B", type: "int" },
  { key: "c", flag: "--c", metavar: "C", type: "string" },
];

const OPTION_MAP = new Map(OPTIONS.map((option) => [option.flag, option]));

function formatUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C\n`;
}

function formatHelp(programName) {
  return [
    `usage: ${programName} [-h] --a A --b B --c C`,
    "",
    "options:",
    "  -h, --help  show this help message and exit",
    "  --a A",
    "  --b B",
    "  --c C",
    "",
  ].join("\n");
}

function parserResult(stream, exitCode, text) {
  return { kind: stream === "stdout" ? "help" : "error", stream, exitCode, text };
}

function parserError(programName, message) {
  return parserResult(
    "stderr",
    2,
    `${formatUsage(programName)}${programName}: error: ${message}\n`,
  );
}

function parseOptionToken(token) {
  if (!token.startsWith("--")) {
    return null;
  }

  const equalsIndex = token.indexOf("=");

  if (equalsIndex === -1) {
    return { flag: token, hasAttachedValue: false, value: "" };
  }

  return {
    flag: token.slice(0, equalsIndex),
    hasAttachedValue: true,
    value: token.slice(equalsIndex + 1),
  };
}

function collectUnknownArgument(extras, argv, index) {
  extras.push(argv[index]);

  if (argv[index].includes("=")) {
    return index;
  }

  const nextToken = argv[index + 1];

  if (nextToken !== undefined && !nextToken.startsWith("-")) {
    extras.push(nextToken);
    return index + 1;
  }

  return index;
}

export function parseCommandLine(argv, programName) {
  const values = {};
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === "-h" || token === "--help") {
      return parserResult("stdout", 0, formatHelp(programName));
    }

    if (token === "--") {
      extras.push(...argv.slice(index + 1));
      break;
    }

    const optionToken = parseOptionToken(token);

    if (optionToken === null) {
      extras.push(token);
      continue;
    }

    const option = OPTION_MAP.get(optionToken.flag);

    if (!option) {
      index = collectUnknownArgument(extras, argv, index);
      continue;
    }

    let rawValue = optionToken.value;

    if (!optionToken.hasAttachedValue) {
      const nextToken = argv[index + 1];

      if (!canConsumeOptionArgument(nextToken)) {
        return parserError(programName, `argument ${option.flag}: expected one argument`);
      }

      rawValue = nextToken;
      index += 1;
    }

    if (option.type === "int") {
      const parsedInteger = parsePythonDecimalBigInt(rawValue);

      if (parsedInteger === null) {
        return parserError(
          programName,
          `argument ${option.flag}: invalid int value: ${pythonStringRepr(rawValue)}`,
        );
      }

      values[option.key] = parsedInteger;
      continue;
    }

    values[option.key] = rawValue;
  }

  if (extras.length > 0) {
    return parserError(programName, `unrecognized arguments: ${extras.join(" ")}`);
  }

  const missing = OPTIONS.filter((option) => !(option.key in values)).map(
    (option) => option.flag,
  );

  if (missing.length > 0) {
    return parserError(
      programName,
      `the following arguments are required: ${missing.join(", ")}`,
    );
  }

  return { kind: "ok", values };
}
